/// Lookup by fixture name; the tests use this instead of an index so a
/// reordering cannot silently point a test at the wrong certificate.
pub fn byName(name: []const u8) *const CertVector {
    for (&certs) |*c| {
        if (std.mem.eql(u8, c.name, name)) return c;
    }
    unreachable;
}

